+//@[pin_project] check-pass
+#![cfg_attr(pin_project, feature(pin_ergonomics))]
+#![feature(if_let_guard)]
+#![allow(incomplete_features)]
+
+use std::pin::Pin;
+
+// This test verifies that a `&pin mut Foo` can be projected to a pinned
+// reference `&pin mut T` of a `?Unpin` field , and can be projected to
+// an unpinned reference `&mut U` of an `Unpin` field .
+
+struct Foo<T, U> {
+    x: T,
+    y: U,
+}
+
+struct Bar<T, U>(T, U);
+
+enum Baz<T, U> {
+    Foo(T, U),
+    Bar { x: T, y: U },
+}
+
+trait IsPinMut {}
+trait IsPinConst {}
+trait IsRefMut {}
+trait IsRef {}
+impl<T: ?Sized> IsPinMut for Pin<&mut T> {}
+impl<T: ?Sized> IsPinConst for Pin<&T> {}
+impl<T: ?Sized> IsRefMut for &mut T {}
+impl<T: ?Sized> IsRef for &T {}
+
+fn assert_pin_mut<T: IsPinMut>(_: T) {}
+fn assert_pin_const<T: IsPinConst>(_: T) {}
+fn assert_ref_mut<T: IsRefMut>(_: T) {}
+fn assert_ref<T: IsRef>(_: T) {}
+
+fn foo_mut<T, U: Unpin>(foo: Pin<&mut Foo<T, U>>) {
+    let Foo { x, y } = foo;
+    //[normal]~^ ERROR mismatched types
+    assert_pin_mut(x);
+    assert_ref_mut(y);
+}

Looking at it now, doing it as a coercion still seems the most promising to me (rather than `unpin!` or similar), though I haven't yet carefully analyzed this for reasons we might not want to do that.  We have many similar coercions around references, and coercing here would seem to fit reasonably well with those.

```rust
fn f1<T: Send>(x: &mut T) -> &T { x }
fn f2<T: Send>(x: &mut T) -> *mut T { x }
fn f3<T: Send>(x: &mut T) -> *const T { x }
fn f4<T: Send>(x: &mut T) -> &mut dyn Send { x }
fn f5<T: Send>(x: &mut T) -> &dyn Send { x }
fn f6<T: Send>(x: &mut T) -> *mut (dyn Send + '_) { x }
fn f7<T: Send>(x: &mut T) -> *const (dyn Send + '_) { x }

// Do we want?:
fn f8<T: Unpin>(x: &pin mut T) -> &mut T { x }
fn f9<T: Unpin>(x: &mut T) -> &pin mut T { x }
```

